css:
.liqmat-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #d7e3ef;
    background: radial-gradient(1200px 480px at 20% -5%, #122a46 0%, #0a1626 45%, #060e1a 100%);
    border-radius: 18px;
}

.liqmat-container * {
    box-sizing: border-box;
}

.liqmat-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0e2238 0%, #15406b 55%, #0c5c63 100%);
    color: #eaf4ff;
    border-radius: 16px;
    margin-bottom: 18px;
    border: 1px solid rgba(96, 165, 215, 0.22);
    box-shadow: 0 16px 40px rgba(3, 10, 20, 0.55);
}

.liqmat-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.liqmat-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #ffd166;
    background: rgba(255, 209, 102, 0.10);
    border: 1px solid rgba(255, 209, 102, 0.36);
    padding: 5px 14px;
    border-radius: 999px;
}

.liqmat-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #bcd2e8;
}

.liqmat-firmstrip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-bottom: 18px;
}

.liqmat-firmfact {
    background: #0e1d31;
    border: 1px solid rgba(96, 165, 215, 0.16);
    border-radius: 12px;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.liqmat-firmfact-k {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #7f9bb8;
}

.liqmat-firmfact-v {
    font-size: 1rem;
    font-weight: 800;
    color: #e7f0fa;
    font-variant-numeric: tabular-nums;
}

.liqmat-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb6cd;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.liqmat-period-counter #currentDay,
.liqmat-period-counter #maxPeriods {
    font-weight: 800;
    color: #34d6c0;
}

.liqmat-round-name {
    background: rgba(52, 214, 192, 0.14);
    color: #46e6ce;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(52, 214, 192, 0.3);
}

.liqmat-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffd166;
    background: rgba(255, 209, 102, 0.12);
    border: 1px solid rgba(255, 209, 102, 0.3);
    padding: 4px 12px;
    border-radius: 999px;
}

.liqmat-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.liqmat-status-card {
    background: linear-gradient(160deg, #102339 0%, #0c1b2c 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid rgba(96, 165, 215, 0.16);
    border-top: 4px solid #3a7bd5;
    box-shadow: 0 8px 22px rgba(3, 10, 20, 0.45);
}

.liqmat-card-multiple { border-top-color: #34d6c0; }
.liqmat-card-spread { border-top-color: #ffd166; }
.liqmat-card-inst { border-top-color: #5aa9ff; }
.liqmat-card-value { border-top-color: #b388ff; }

.liqmat-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8aa3bd;
}

.liqmat-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #eaf4ff;
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.5px;
}

.liqmat-card-multiple .liqmat-value { color: #34d6c0; }
.liqmat-card-spread .liqmat-value { color: #ffd166; }
.liqmat-card-inst .liqmat-value { color: #5aa9ff; }
.liqmat-card-value .liqmat-value { color: #b388ff; }

.liqmat-sublabel {
    font-size: 0.74rem;
    color: #7f9bb8;
    line-height: 1.35;
}

.liqmat-card-multiple.liqmat-mult-good .liqmat-value { color: #46e6ce; }
.liqmat-card-multiple.liqmat-mult-bad .liqmat-value { color: #ff6b6b; }
.liqmat-card-spread.liqmat-spread-good .liqmat-value { color: #46e6ce; }
.liqmat-card-spread.liqmat-spread-bad .liqmat-value { color: #ff6b6b; }

.liqmat-discount-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0e1d31;
    border: 1px solid rgba(96, 165, 215, 0.18);
    color: #9fb6cd;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.liqmat-discount-bar #discountDisplay {
    font-size: 1.15rem;
    letter-spacing: 0.3px;
    color: #ff6b6b;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.liqmat-discount-bar.liqmat-discount-mid #discountDisplay { color: #ffd166; }
.liqmat-discount-bar.liqmat-discount-low #discountDisplay { color: #46e6ce; }

.liqmat-briefing {
    display: flex;
    gap: 14px;
    background: #0e1d31;
    border: 1px solid rgba(96, 165, 215, 0.16);
    border-left: 5px solid #34d6c0;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(3, 10, 20, 0.4);
}

.liqmat-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.liqmat-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #eaf4ff;
    margin-bottom: 6px;
}

.liqmat-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c2d5e8;
}

.liqmat-briefing-text strong { color: #5aa9ff; }
.liqmat-briefing-text em { color: #ffd166; font-style: italic; }

.liqmat-controls {
    background: #0e1d31;
    border: 1px solid rgba(96, 165, 215, 0.16);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(3, 10, 20, 0.4);
}

.liqmat-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #eaf4ff;
    border-bottom: 2px solid rgba(96, 165, 215, 0.18);
    padding-bottom: 8px;
}

.liqmat-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #c2d5e8;
    margin: 14px 0 6px;
}

.liqmat-container select,
.liqmat-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2a4863;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0a1626;
    color: #e7f0fa;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.liqmat-container select:focus,
.liqmat-container input[type="number"]:focus {
    outline: none;
    border-color: #34d6c0;
    box-shadow: 0 0 0 3px rgba(52, 214, 192, 0.18);
}

.liqmat-container select option {
    background-color: #0a1626;
    color: #e7f0fa;
}

.liqmat-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #34d6c0;
}

.liqmat-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb6cd;
    margin-top: 4px;
}

.liqmat-range-readout span:nth-child(2) {
    color: #34d6c0;
    font-weight: 800;
}

.liqmat-hint {
    font-size: 0.8rem;
    color: #7f9bb8;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.liqmat-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.liqmat-container .btn-primary {
    background: linear-gradient(135deg, #15806f 0%, #34d6c0 100%);
    border: none;
    color: #042019;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 10px 22px rgba(52, 214, 192, 0.28);
}

.liqmat-container .btn-primary:hover {
    filter: brightness(1.08);
}

.liqmat-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #2a4863;
    color: #9fb6cd;
    background: transparent;
}

.liqmat-coach {
    background: linear-gradient(160deg, #0e2238 0%, #102a48 100%);
    color: #d7e7f5;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(96, 165, 215, 0.2);
    box-shadow: 0 10px 24px rgba(3, 10, 20, 0.45);
}

.liqmat-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd166;
    margin-bottom: 8px;
}

.liqmat-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.liqmat-coach-body strong { color: #46e6ce; }
.liqmat-coach-body em { color: #ffd166; font-style: italic; }

.liqmat-history,
.liqmat-chart {
    background: #0e1d31;
    border: 1px solid rgba(96, 165, 215, 0.16);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(3, 10, 20, 0.4);
}

.liqmat-history h3,
.liqmat-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #eaf4ff;
}

.liqmat-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c2d5e8;
}

.liqmat-container table#usfHistoryTable th {
    background: #12273f;
    color: #5aa9ff;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #1f3b58;
}

.liqmat-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #16293f;
    color: #c2d5e8;
}

.liqmat-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0c1b2c;
}

.liqmat-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .liqmat-container {
        padding: 14px;
    }
    .liqmat-header h1 {
        font-size: 1.7rem;
    }
    .liqmat-firmstrip {
        grid-template-columns: repeat(2, 1fr);
    }
    .liqmat-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .liqmat-value {
        font-size: 2rem;
    }
    .liqmat-clock {
        margin-left: 0;
    }
    .liqmat-period-counter {
        font-size: 0.88rem;
    }
    .liqmat-discount-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .liqmat-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (liq- prefix; Euronext teal theme) ---- */
.liq-completion { padding: 8px 4px 4px; }
.liq-cm-head { text-align: center; margin-bottom: 16px; }
.liq-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f9c8a; }
.liq-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #8aa3bd; }
.liq-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #14322e; }
.liq-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.liq-cm-yes { background: rgba(31,156,138,0.15); color: #1f9c8a; border: 1px solid rgba(31,156,138,0.45); }
.liq-cm-mid { background: rgba(138,163,189,0.15); color: #5f7286; border: 1px solid rgba(138,163,189,0.42); }
.liq-cm-no  { background: rgba(200,64,52,0.12); color: #c84034; border: 1px solid rgba(200,64,52,0.42); }
.liq-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.liq-cm-metric { flex: 1 1 100px; min-width: 92px; background: rgba(31,156,138,0.07); border: 1px solid rgba(31,156,138,0.20); border-radius: 10px; padding: 10px 8px; text-align: center; }
.liq-cm-mv { display: block; font-size: 1.15rem; font-weight: 800; color: #1f9c8a; }
.liq-cm-ml { display: block; font-size: 0.66rem; margin-top: 4px; color: #8aa3bd; text-transform: uppercase; letter-spacing: 0.03em; }
.liq-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #14322e; }
.liq-cm-insights { margin: 0; padding-left: 20px; }
.liq-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #38484f; }

