(function() {
    'use strict';

    class LiquidityMattersAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Liquidity Matters`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Lumiform S.A. / Euronext Paris).
            this.START_MULTIPLE = 7.2;     // Lumiform EV/EBITDA
            this.PEER_MULTIPLE = 9.0;      // peers — the target
            this.EBITDA = 76;              // EUR M
            this.START_SPREAD = 65;        // bid-ask, bp
            this.LP_SPREAD = 40;           // illustrative spread with a market maker, bp
            this.START_INST = 31;          // institutional ownership, %
            this.FAMILY = 28;              // family ownership, %
            this.MAX_VALUE = Math.round((this.PEER_MULTIPLE - this.START_MULTIPLE) * this.EBITDA); // ~137 EUR M
            this.BLOCK_EUR = 39;           // EUR M, the 9% block

            // KPI caps imposed by the run-defining error flags.
            this.CAP_EARNINGS = 7.8;       // earnings tunnel vision can't re-rate past here
            this.CAP_BLOCK = 7.9;          // a distress block print caps the multiple
            this.CAP_PLUMBING = 8.3;       // liquidity without demand is a half-fix
            this.CAP_CONTROL_MULT = 8.2;   // entrenched control caps the re-rating
            this.CAP_CONTROL_INST = 38;    // and caps institutional ownership
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    multiple: this.START_MULTIPLE,    // EV/EBITDA turns
                    spread: this.START_SPREAD,        // bid-ask, bp
                    inst: this.START_INST,            // institutional ownership, %
                    evRecovered: 0,                   // EUR M of the ~137M closed
                    discount: Math.round((this.PEER_MULTIPLE - this.START_MULTIPLE) / this.PEER_MULTIPLE * 100), // %
                    // Sticky run-defining error flags — set when an error is committed,
                    // they GATE the top verdict and CAP KPIs (a later good round cannot wash them out).
                    earningsTunnelRun: false,         // tried to fix a liquidity discount with earnings alone
                    controlEntrenchedRun: false,      // kept entrenching structures, expected peer multiples anyway
                    blockDumpedRun: false,            // dumped the block / deep distress print
                    plumbingOnlyRun: false,           // bought liquidity plumbing without demand
                    panicRun: false,                  // confused a market-wide fall with firm-specific repricing
                    lpEngaged: false,                 // a market maker is under contract
                    govCredible: false,               // genuine governance reform landed
                    multipleHistory: [this.START_MULTIPLE],
                    spreadHistory: [this.START_SPREAD],
                    instHistory: [this.START_INST],
                    valueHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    driver: `earnings`,
                    chain: `direct`,
                    valueAtStake: `zero`,
                    conviction: 35,
                    voting: `keep`,
                    board: `status_quo`,
                    lp: `none`,
                    sequence: `overhaul`,
                    ir: `none`,
                    block: `dump`,
                    shock: `panic_buyback`,
                    placement: 12,
                    thesis: `earnings`,
                    control: `ignore`,
                    probe: `overpromise`,
                    horizon: 45
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dr = document.getElementById(`driverInput`);
                const ch = document.getElementById(`chainInput`);
                const va = document.getElementById(`valueAtStakeInput`);
                const cv = document.getElementById(`convictionInput`);
                if (dr) decisions.driver = dr.value;
                if (ch) decisions.chain = ch.value;
                if (va) decisions.valueAtStake = va.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            } else if (round === 2) {
                const vo = document.getElementById(`votingInput`);
                const bo = document.getElementById(`boardInput`);
                const lp = document.getElementById(`lpInput`);
                const se = document.getElementById(`sequenceInput`);
                if (vo) decisions.voting = vo.value;
                if (bo) decisions.board = bo.value;
                if (lp) decisions.lp = lp.value;
                if (se) decisions.sequence = se.value;
            } else if (round === 3) {
                const ir = document.getElementById(`irInput`);
                const bl = document.getElementById(`blockInput`);
                const sh = document.getElementById(`shockInput`);
                const pl = document.getElementById(`placementInput`);
                if (ir) decisions.ir = ir.value;
                if (bl) decisions.block = bl.value;
                if (sh) decisions.shock = sh.value;
                if (pl) decisions.placement = parseInt(pl.value, 10);
                if (!Number.isFinite(decisions.placement) || decisions.placement < 0 || decisions.placement > 20) {
                    warn(`warn_placement_range`); return false;
                }
            } else if (round === 4) {
                const th = document.getElementById(`thesisInput`);
                const co = document.getElementById(`controlInput`);
                const pr = document.getElementById(`probeInput`);
                const ho = document.getElementById(`horizonInput`);
                if (th) decisions.thesis = th.value;
                if (co) decisions.control = co.value;
                if (pr) decisions.probe = pr.value;
                if (ho) decisions.horizon = parseInt(ho.value, 10);
                if (!Number.isFinite(decisions.horizon) || decisions.horizon < 0 || decisions.horizon > 100) {
                    warn(`warn_horizon_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Per-round deltas. multiple in turns, spread in bp, inst in %.
            let multDelta = 0, spreadDelta = 0, instDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the liquidity–value chain (Common Error 1: earnings tunnel vision).
                switch (d.driver) {
                    case `liqgov`: multDelta += 0.10; coachKey = `coach_r1_liqgov`; break;
                    case `earnings`: ds.earningsTunnelRun = true; multDelta -= 0.05; coachKey = `coach_r1_earnings`; break;
                    case `macro`: ds.earningsTunnelRun = true; multDelta -= 0.05; coachKey = `coach_r1_macro`; break;
                }

                switch (d.chain) {
                    case `costs`: multDelta += 0.12; instDelta += 1; if (d.driver === `liqgov`) coachKey = `coach_r1_sharp`; break;
                    case `direct`: ds.earningsTunnelRun = true; coachKey = `coach_r1_chaindirect`; break;
                    case `none`: ds.earningsTunnelRun = true; multDelta -= 0.05; coachKey = `coach_r1_chainnone`; break;
                }

                switch (d.valueAtStake) {
                    case `real`: multDelta += 0.05; break;
                    case `small`: break;
                    case `zero`: ds.earningsTunnelRun = true; coachKey = `coach_r1_valuezero`; break;
                }

                // Conviction in the liquidity–value thesis sets the tone for the whole plan.
                if (d.conviction >= 60) { multDelta += 0.05; }
                else if (d.conviction <= 25) { multDelta -= 0.05; if (coachKey === `coach_default`) coachKey = `coach_r1_lowconv`; }

                summaryKey = (d.driver === `liqgov` && d.chain === `costs` && d.valueAtStake === `real`) ? `sum_r1_good` :
                             (ds.earningsTunnelRun ? `sum_r1_tunnel` : `sum_r1_weak`);
            } else if (round === 2) {
                // Listing & governance structure — the control-vs-value trade-off (Common Errors 2 & 5).
                // Voting structure.
                switch (d.voting) {
                    case `sunset`: instDelta += 7; multDelta += 0.55; ds.govCredible = true; coachKey = `coach_r2_sunset`; break;
                    case `keep`: ds.controlEntrenchedRun = true; instDelta += 1; coachKey = `coach_r2_keep`; break;
                    case `scrap_now`: instDelta += 4; multDelta += 0.15; coachKey = `coach_r2_scrapnow`; break; // alienates the family coalition
                }

                // Board independence + listing compartment.
                switch (d.board) {
                    case `independents`: instDelta += 6; multDelta += 0.45; ds.govCredible = true; break;
                    case `status_quo`: ds.controlEntrenchedRun = true; instDelta -= 1; if (coachKey === `coach_default`) coachKey = `coach_r2_statusquo`; break;
                    case `cosmetic`: instDelta += 1; coachKey = `coach_r2_cosmetic`; break;
                }

                // Liquidity provider — improves the ABILITY to trade (the spread), not demand.
                if (d.lp === `yes`) {
                    ds.lpEngaged = true;
                    spreadDelta -= (this.START_SPREAD - this.LP_SPREAD); // 65 -> ~40 bp
                    multDelta += 0.20;
                } else {
                    if (coachKey === `coach_default`) coachKey = `coach_r2_nolp`;
                }

                // Sequencing discipline (Common Error 5: over-engineering with no order).
                switch (d.sequence) {
                    case `focused`: multDelta += 0.30; instDelta += 2; if (d.voting === `sunset` && d.board === `independents`) coachKey = `coach_r2_focused`; break;
                    case `overhaul`: multDelta -= 0.25; instDelta -= 1; coachKey = `coach_r2_overhaul`; break; // family revolt, no idea which lever worked
                    case `nothing`: multDelta -= 0.20; coachKey = `coach_r2_nothing`; break;
                }

                summaryKey = (!ds.controlEntrenchedRun && ds.govCredible && d.sequence === `focused`) ? `sum_r2_good` :
                             (ds.controlEntrenchedRun ? `sum_r2_control` :
                             (d.sequence === `overhaul` ? `sum_r2_overhaul` : `sum_r2_weak`));
            } else if (round === 3) {
                // IR move & block management, plus the mid-round shock (Common Errors 3, 4 & 5... and 6: price vs value).
                // IR — the DEMAND lever.
                switch (d.ir) {
                    case `full`: instDelta += 8; multDelta += 0.45; ds.plumbingOnlyRun = false; break;
                    case `plumbing`: if (ds.lpEngaged) { ds.plumbingOnlyRun = true; } instDelta += 1; coachKey = `coach_r3_plumbing`; break;
                    case `none`: if (ds.lpEngaged) { ds.plumbingOnlyRun = true; } instDelta -= 1; coachKey = `coach_r3_irnone`; break;
                }

                // Block management (Common Error 3: mishandling the block).
                switch (d.block) {
                    case `placement`:
                        instDelta += 5; multDelta += 0.35;
                        // A modest, pre-agreed discount reads as confidence; a deep one still signals distress.
                        if (d.placement <= 6) { multDelta += 0.15; }
                        else if (d.placement >= 13) { ds.blockDumpedRun = true; multDelta -= 0.30; coachKey = `coach_r3_deepplacement`; }
                        break;
                    case `buyback`:
                        // Removes the overhang but leverages the balance sheet; not distress if disciplined.
                        multDelta += 0.10; spreadDelta += 2;
                        if (d.placement >= 13) { multDelta -= 0.10; }
                        coachKey = `coach_r3_buyback`;
                        break;
                    case `dump`:
                        ds.blockDumpedRun = true;
                        multDelta -= 0.50; spreadDelta += 12; instDelta -= 4;
                        coachKey = `coach_r3_dump`;
                        break;
                }

                // The mid-round liquidity shock (Common Error 6: confusing price with value).
                switch (d.shock) {
                    case `hold`:
                        multDelta += 0.20;
                        if (d.block === `placement` && d.ir === `full`) coachKey = `coach_r3_hold`;
                        break;
                    case `panic_buyback`:
                        ds.panicRun = true; multDelta -= 0.25; spreadDelta += 4;
                        coachKey = `coach_r3_panic`;
                        break;
                    case `abandon`:
                        ds.panicRun = true; multDelta -= 0.30; instDelta -= 3;
                        coachKey = `coach_r3_abandon`;
                        break;
                }

                summaryKey = (d.ir === `full` && d.block === `placement` && d.shock === `hold` && !ds.blockDumpedRun) ? `sum_r3_good` :
                             (ds.blockDumpedRun ? `sum_r3_block` :
                             (ds.panicRun ? `sum_r3_panic` :
                             (ds.plumbingOnlyRun ? `sum_r3_plumbing` : `sum_r3_weak`)));
            } else if (round === 4) {
                // The re-rating case to the board and the activist fund.
                switch (d.thesis) {
                    case `chain`: multDelta += 0.45; instDelta += 3; coachKey = `coach_r4_chain`; break;
                    case `earnings`: ds.earningsTunnelRun = true; multDelta -= 0.10; coachKey = `coach_r4_earnings`; break;
                    case `plumbing`: if (ds.lpEngaged) ds.plumbingOnlyRun = true; coachKey = `coach_r4_plumbing`; break;
                }

                switch (d.control) {
                    case `coalition`: instDelta += 4; multDelta += 0.30; if (!ds.controlEntrenchedRun) ds.govCredible = true; if (d.thesis === `chain`) coachKey = `coach_r4_coalition`; break;
                    case `ignore`: multDelta -= 0.10; coachKey = `coach_r4_ignore`; break;
                    case `capitulate`: ds.controlEntrenchedRun = true; instDelta -= 1; coachKey = `coach_r4_capitulate`; break;
                }

                switch (d.probe) {
                    case `credible`: multDelta += 0.25; instDelta += 2; if (d.control === `coalition` && d.thesis === `chain`) coachKey = `coach_r4_credible`; break;
                    case `overpromise`: multDelta -= 0.15; coachKey = `coach_r4_overpromise`; break;
                    case `dismiss`: multDelta -= 0.20; instDelta -= 2; coachKey = `coach_r4_dismiss`; break;
                }

                // A credible multi-quarter horizon (vs claiming overnight closure).
                if (d.horizon >= 60) { multDelta += 0.10; }
                else if (d.horizon <= 25) { multDelta -= 0.10; }

                summaryKey = (d.thesis === `chain` && d.control === `coalition` && d.probe === `credible`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply raw deltas. ----
            ds.multiple = Math.round((ds.multiple + multDelta) * 100) / 100;
            ds.spread = Math.max(20, Math.round(ds.spread + spreadDelta));
            ds.inst = Math.max(0, Math.min(100, Math.round((ds.inst + instDelta) * 10) / 10));

            // ---- Apply STICKY run-defining caps. These gate the re-rating no matter
            // how well later rounds are played. ----
            if (ds.earningsTunnelRun) ds.multiple = Math.min(ds.multiple, this.CAP_EARNINGS);
            if (ds.blockDumpedRun) ds.multiple = Math.min(ds.multiple, this.CAP_BLOCK);
            if (ds.controlEntrenchedRun) {
                ds.multiple = Math.min(ds.multiple, this.CAP_CONTROL_MULT);
                ds.inst = Math.min(ds.inst, this.CAP_CONTROL_INST);
            }
            // Plumbing-without-demand: a market maker but no governance/IR demand caps the re-rating.
            if (ds.lpEngaged && ds.plumbingOnlyRun && !ds.govCredible) {
                ds.multiple = Math.min(ds.multiple, this.CAP_PLUMBING);
            }

            // Floor at the starting multiple — you cannot trade BELOW the day-one discount here.
            ds.multiple = Math.max(this.START_MULTIPLE - 0.4, Math.min(this.PEER_MULTIPLE, Math.round(ds.multiple * 100) / 100));

            // ---- Derived KPIs. ----
            ds.discount = Math.max(0, Math.round((this.PEER_MULTIPLE - ds.multiple) / this.PEER_MULTIPLE * 100));
            let recovered = Math.round((ds.multiple - this.START_MULTIPLE) * this.EBITDA);
            // A panic run buys high in a market-wide fall — value recovered is discounted.
            if (ds.panicRun) recovered = Math.round(recovered * 0.7);
            ds.evRecovered = Math.max(0, Math.min(this.MAX_VALUE, recovered));

            ds.multipleHistory.push(ds.multiple);
            ds.spreadHistory.push(ds.spread);
            ds.instHistory.push(ds.inst);
            ds.valueHistory.push(ds.evRecovered);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist composite score + grade to the reporting/grading layer every period.
            // (results_utils.php::express_resolveDomainScore -> performance.overallScore). Scoring UNCHANGED.
            const _score = this._composite(ds);
            ds.performance = { overallScore: _score, grade: this._gradeLetter(_score) };

            return {
                period: state.currentPeriod,
                multiple: ds.multiple,
                multDelta: Math.round(multDelta * 100) / 100,
                spread: ds.spread,
                inst: ds.inst,
                evRecovered: ds.evRecovered,
                discount: ds.discount,
                earningsTunnelRun: ds.earningsTunnelRun,
                controlEntrenchedRun: ds.controlEntrenchedRun,
                blockDumpedRun: ds.blockDumpedRun,
                plumbingOnlyRun: ds.plumbingOnlyRun,
                panicRun: ds.panicRun,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                overallScore: _score,
                score: _score
            };
        }

        _fmtMultiple(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(Number(v) * 10) / 10).toFixed(1);
            return (lang === `es` ? s.replace(`.`, `,`) : s) + `x`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`multipleDisplay`, `domainState.multiple`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.liqmat-card-multiple`);
                if (card) {
                    card.classList.toggle(`liqmat-mult-good`, n >= 8.6);
                    card.classList.toggle(`liqmat-mult-bad`, n <= self.START_MULTIPLE + 0.05);
                }
                return self._fmtMultiple(n);
            });

            uiManager.bind(`spreadDisplay`, `domainState.spread`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.liqmat-card-spread`);
                if (card) {
                    card.classList.toggle(`liqmat-spread-good`, n <= 45);
                    card.classList.toggle(`liqmat-spread-bad`, n >= 70);
                }
                return `${n} bp`;
            });

            uiManager.bind(`instDisplay`, `domainState.inst`, (v) => `${Math.round(Number(v))}%`);

            uiManager.bind(`valueDisplay`, `domainState.evRecovered`, (v) => `€${Math.round(Number(v))}M`);

            uiManager.bind(`discountDisplay`, `domainState.discount`, (v) => {
                const n = Math.round(Number(v));
                const bar = document.querySelector(`.liqmat-discount-bar`);
                if (bar) {
                    bar.classList.toggle(`liqmat-discount-low`, n <= 6);
                    bar.classList.toggle(`liqmat-discount-mid`, n > 6 && n <= 13);
                }
                return `${n}%`;
            });

            // Conviction slider readout (Round 1).
            const cv = document.getElementById(`convictionInput`);
            const cvReadout = document.getElementById(`convictionReadout`);
            if (cv && cvReadout) {
                cvReadout.textContent = cv.value;
                cv.addEventListener(`input`, function() { cvReadout.textContent = cv.value; });
            }

            // Placement-discount slider readout (Round 3).
            const pl = document.getElementById(`placementInput`);
            const plReadout = document.getElementById(`placementReadout`);
            if (pl && plReadout) {
                plReadout.textContent = pl.value;
                pl.addEventListener(`input`, function() { plReadout.textContent = pl.value; });
            }
        }

        getChartConfig() {
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : null;
            const L = (k, en) => (t ? t(k) : en);
            return {
                liquidityChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L(`chart_ds_multiple`, `EV/EBITDA multiple (turns)`),
                                data: [],
                                borderColor: `#34d6c0`,
                                backgroundColor: `rgba(52,214,192,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#34d6c0`,
                                yAxisID: `yMult`
                            },
                            {
                                label: L(`chart_ds_inst`, `Institutional ownership (%)`),
                                data: [],
                                borderColor: `#5aa9ff`,
                                backgroundColor: `rgba(90,169,255,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#5aa9ff`,
                                yAxisID: `yPct`
                            },
                            {
                                label: L(`chart_ds_spread`, `Bid-ask spread (bp)`),
                                data: [],
                                borderColor: `#ffd166`,
                                backgroundColor: `rgba(255,209,102,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
