                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.multipleHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                liquidityChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.multipleHistory.map((v) => Math.round(v * 100) / 100) },
                        { data: ds.instHistory.map((v) => Math.round(v)) },
                        { data: ds.spreadHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            const multiple = Math.round(ds.multiple * 100) / 100;
            const spread = Math.round(ds.spread);
            const inst = Math.round(ds.inst);
            const evRecovered = Math.round(ds.evRecovered);
            const reRate = Math.max(0, Math.min(1, (multiple - this.START_MULTIPLE) / (this.PEER_MULTIPLE - this.START_MULTIPLE)));
            const spreadGain = Math.max(0, Math.min(1, (this.START_SPREAD - spread) / (this.START_SPREAD - this.LP_SPREAD)));
            const instGain = Math.max(0, Math.min(1, (inst - this.START_INST) / (50 - this.START_INST)));
            const valueGain = Math.max(0, Math.min(1, evRecovered / this.MAX_VALUE));
            return Math.round((reRate * 0.42 + valueGain * 0.28 + instGain * 0.18 + spreadGain * 0.12) * 100);
        }

        _verdictKey(ds, composite) {
            const multiple = Math.round(ds.multiple * 100) / 100;
            const spread = Math.round(ds.spread);
            const inst = Math.round(ds.inst);
            const evRecovered = Math.round(ds.evRecovered);
            const reRated = multiple >= 8.6;
            const tightened = spread <= 48;
            const institutionalised = inst >= 44;
            const valuableClose = evRecovered >= 90;
            const anyError = ds.earningsTunnelRun || ds.controlEntrenchedRun || ds.blockDumpedRun ||
                             (ds.plumbingOnlyRun && !ds.govCredible) || ds.panicRun;
            if (!anyError && reRated && institutionalised && valuableClose && tightened && composite >= 78) return `verdict_rerated`;
            if (!anyError && reRated && valuableClose && composite >= 60) return `verdict_narrowed`;
            if (ds.blockDumpedRun) return `verdict_distress`;
            if (ds.earningsTunnelRun) return `verdict_earnings`;
            if (ds.controlEntrenchedRun) return `verdict_control`;
            if (ds.plumbingOnlyRun && !ds.govCredible) return `verdict_plumbing`;
            if (ds.panicRun) return `verdict_panic`;
            if (composite >= 45) return `verdict_partial`;
            return `verdict_persists`;
        }

        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 75) return `B`;
            if (c >= 62) return `C`;
            if (c >= 50) return `D`;
            if (c >= 35) return `E`;
            return `F`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const multiple = Math.round(ds.multiple * 100) / 100;
            const spread = Math.round(ds.spread);
            const inst = Math.round(ds.inst);
            const evRecovered = Math.round(ds.evRecovered);
            const discount = Math.round(ds.discount);

            // Composite (0–100): re-rating progress, spread tightening, institutional gain, value recovered.
            const composite = this._composite(ds);

            const reRated = multiple >= 8.6;
            const tightened = spread <= 48;
            const institutionalised = inst >= 44;
            const valuableClose = evRecovered >= 90;

            const anyError = ds.earningsTunnelRun || ds.controlEntrenchedRun || ds.blockDumpedRun ||
                             (ds.plumbingOnlyRun && !ds.govCredible) || ds.panicRun;

            // Pattern label — the headline anti-pattern, if any, dominates.
            let pattern = `mixed`;
            if (ds.blockDumpedRun) pattern = `block`;
            else if (ds.earningsTunnelRun) pattern = `earnings`;
            else if (ds.controlEntrenchedRun) pattern = `control`;
            else if (ds.plumbingOnlyRun && !ds.govCredible) pattern = `plumbing`;
            else if (ds.panicRun) pattern = `panic`;
            else if (reRated && institutionalised && valuableClose) pattern = `rerate`;

            // Performance verdict — the TOP verdict is GATED: any run-defining error blocks it.
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const verdictKey = this._verdictKey(ds, composite);
            const performance = T(verdictKey);

            const insights = [];
            if (pattern === `rerate` && !anyError) insights.push(window.mySimulation.t(`insight_rerate`));
            else if (pattern === `block`) insights.push(window.mySimulation.t(`insight_block`));
            else if (pattern === `earnings`) insights.push(window.mySimulation.t(`insight_earnings`));
            else if (pattern === `control`) insights.push(window.mySimulation.t(`insight_control`));
            else if (pattern === `plumbing`) insights.push(window.mySimulation.t(`insight_plumbing`));
            else if (pattern === `panic`) insights.push(window.mySimulation.t(`insight_panic`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!tightened && ds.lpEngaged === false) insights.push(window.mySimulation.t(`insight_spread_wide`));
            if (!institutionalised) insights.push(window.mySimulation.t(`insight_inst_low`));
            if (ds.govCredible && reRated) insights.push(window.mySimulation.t(`insight_gov_paid`));
            if (evRecovered >= this.MAX_VALUE - 5) insights.push(window.mySimulation.t(`insight_value_full`));

            return {
                multiple: multiple,
                spread: spread,
                inst: inst,
                evRecovered: evRecovered,
                discount: discount,
                reRated: reRated,
                tightened: tightened,
                institutionalised: institutionalised,
                valuableClose: valuableClose,
                pattern: pattern,
                composite: composite,
                overallScore: composite,
                verdictKey: verdictKey,
                grade: this._gradeLetter(composite),
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? (k) => window.mySimulation.t(k) : (k) => k;
            const s = summary || {};
            const score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            const grade = s.grade || '';
            const verdict = s.performance || (s.verdictKey ? T(s.verdictKey) : '');
            const multiple = this._fmtMultiple(Number(s.multiple || 0));
            const spread = Math.round(Number(s.spread || 0)) + ' bp';
            const inst = Math.round(Number(s.inst || 0)) + '%';
            const value = '\u20AC' + Math.round(Number(s.evRecovered || 0)) + 'M';
            const discount = Math.round(Number(s.discount || 0)) + '%';
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map((t) => '<li>' + t + '</li>').join('');
            const rerated = s.verdictKey === 'verdict_rerated';
            const badgeCls = rerated ? 'liq-cm-yes' : (score >= 62 ? 'liq-cm-mid' : 'liq-cm-no');
            const metric = (val, lab) => '<div class="liq-cm-metric"><span class="liq-cm-mv">' + val + '</span><span class="liq-cm-ml">' + lab + '</span></div>';
            const metrics = metric(multiple, T('cm_m_multiple'))
                + metric(spread, T('cm_m_spread'))
                + metric(inst, T('cm_m_inst'))
                + metric(value, T('cm_m_value'))
                + metric(discount, T('cm_m_discount'));
            return ''
                + '<div class="liq-completion">'
                +   '<div class="liq-cm-head">'
                +     '<div class="liq-cm-score">' + score + '<span class="liq-cm-score-max">/100</span></div>'
                +     '<div class="liq-cm-grade">' + verdict + ' <span class="liq-cm-badge ' + badgeCls + '">' + T('cm_grade') + ' ' + grade + '</span></div>'
                +   '</div>'
                +   '<div class="liq-cm-metrics">' + metrics + '</div>'
                +   '<div class="liq-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="liq-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.blockDumpedRun) return window.mySimulation.t(`hint_block`);
            if (ds.earningsTunnelRun) return window.mySimulation.t(`hint_earnings`);
            if (ds.controlEntrenchedRun) return window.mySimulation.t(`hint_control`);
            if (ds.lpEngaged && ds.plumbingOnlyRun && !ds.govCredible) return window.mySimulation.t(`hint_plumbing`);
            if (ds.panicRun) return window.mySimulation.t(`hint_panic`);
            if (ds.multiple >= 8.6 && ds.inst >= 44) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.multiple`, label: `Multiple`, i18nKey: `col_multiple`, formatter: (v) => self._fmtMultiple(Number(v)) },
                { key: `results.spread`, label: `Spread`, i18nKey: `col_spread`, formatter: (v) => `${Math.round(v)} bp` },
                { key: `results.inst`, label: `Institutional`, i18nKey: `col_inst`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.evRecovered`, label: `EV recovered`, i18nKey: `col_value`, formatter: (v) => `€${Math.round(v)}M` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
